/**
 * Retries processing of failed import job with same data
 * @summary Retry failed import
 */
export type resumeImportRetryResponse201 = {
  data: ImportResultDto
  status: 201
}

export type resumeImportRetryResponse401 = {
  data: void
  status: 401
}
    
export type resumeImportRetryResponseSuccess = (resumeImportRetryResponse201) & {
  headers: Headers;
};
export type resumeImportRetryResponseError = (resumeImportRetryResponse401) & {
  headers: Headers;
};

export type resumeImportRetryResponse = (resumeImportRetryResponseSuccess | resumeImportRetryResponseError)

export const getResumeImportRetryUrl = (importId: string,) => {


  

  return `/api/resume-import/${importId}/retry`
}

export const resumeImportRetry = async (importId: string,
    retryImportRequestDto: RetryImportRequestDto, options?: RequestInit): Promise<resumeImportRetryResponse> => {
  
  return customFetch<resumeImportRetryResponse>(getResumeImportRetryUrl(importId),
  {      
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      retryImportRequestDto,)
  }
);}




export const getResumeImportRetryMutationOptions = <TError = void,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof resumeImportRetry>>, TError,{importId: string;data: RetryImportRequestDto}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof resumeImportRetry>>, TError,{importId: string;data: RetryImportRequestDto}, TContext> => {

const mutationKey = ['resumeImportRetry'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};

      


      const mutationFn: MutationFunction<Awaited<ReturnType<typeof resumeImportRetry>>, {importId: string;data: RetryImportRequestDto}> = (props) => {
          const {importId,data} = props ?? {};

          return  resumeImportRetry(importId,data,requestOptions)
        }



        


  return  { mutationFn, ...mutationOptions }}

    export type ResumeImportRetryMutationResult = NonNullable<Awaited<ReturnType<typeof resumeImportRetry>>>
    export type ResumeImportRetryMutationBody = RetryImportRequestDto
    export type ResumeImportRetryMutationError = void

    /**
 * @summary Retry failed import
 */
